// Validate admin access
const body = $input.item.json.body || {};
const headers = $input.item.json.headers || {};

if (!headers.authorization) {
  throw new Error('Missing Authorization header');
}

// Extract JWT claims
const token = headers.authorization.replace('Bearer ', '');
const claims = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());

if (!claims.role || !['master', 'administrator'].includes(claims.role)) {
  throw new Error('Access denied: admin role required');
}

return {
  json: {
    org_id: body.org_id || null,
    municipality: body.municipality || null,
    state: body.state || null,
    status_filter: body.status || null,
    limit: body.limit || 50,
    offset: body.offset || 0
  }
};

// Build query filters
const filters = $input.item.json;
let whereClause = 'WHERE 1=1';
const params = [];

if (filters.org_id) {
  whereClause += ` AND ct.organization_id = ${filters.org_id}`;
}

if (filters.municipality) {
  whereClause += ` AND ct.municipality = '${filters.municipality}'`;
}

if (filters.state) {
  whereClause += ` AND ct.state = '${filters.state}'`;
}

return {
  json: {
    ...filters,
    where_clause: whereClause
  }
};

// Format processes list
const processes = $input.all().map(item => item.json);

return {
  json: {
    status: 'success',
    total: processes.length,
    processes: processes.map(p => ({
      thread_id: p.id,
      title: p.title,
      municipality: p.municipality,
      state: p.state,
      org_id: p.organization_id,
      org_name: p.org_name,
      files_count: parseInt(p.files_count) || 0,
      last_update: p.last_update
    }))
  }
};

// Validate reprocess request
const body = $input.item.json.body || {};
const headers = $input.item.json.headers || {};

if (!headers.authorization) {
  throw new Error('Missing Authorization header');
}

if (!body.thread_id || !body.org_id) {
  throw new Error('Missing required fields: thread_id, org_id');
}

const token = headers.authorization.replace('Bearer ', '');
const claims = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());

if (!claims.role || !['master', 'administrator'].includes(claims.role)) {
  throw new Error('Access denied: admin role required');
}

return {
  json: {
    thread_id: body.thread_id,
    org_id: body.org_id,
    force: body.force || false
  }
};

// Prepare reprocessing tasks
const data = $('Validate Reprocess').item.json;
const files = $input.all().map(item => item.json);

return {
  json: {
    thread_id: data.thread_id,
    org_id: data.org_id,
    files_to_reprocess: files.length,
    file_ids: files.map(f => f.id),
    force: data.force
  }
};

// Build reprocess response
const data = $('Prepare Reprocess').item.json;

return {
  json: {
    status: 'success',
    message: 'Reprocessing initiated',
    thread_id: data.thread_id,
    files_queued: data.files_to_reprocess
  }
};

// Health check
const checks = {
  timestamp: new Date().toISOString(),
  service: 'n8n-admin-console',
  status: 'healthy'
};

return { json: checks };

// Aggregate health data
const baseHealth = $('Health Check').item.json;
const dbData = $('Check Database').item.json;
const connData = $('Check Connections').all().map(item => item.json);

return {
  json: {
    ...baseHealth,
    database: {
      status: 'connected',
      active_orgs: parseInt(dbData.total_orgs) || 0
    },
    connections: {
      total_configured: connData.length,
      by_org: connData
    }
  }
};
